install_template:
mkdir -p {src_dir} && if [ -d {src_dir}/deepseek-v4-flash-0731-spark-sparkinfer/.git ]; then git -C {src_dir}/deepseek-v4-flash-0731-spark-sparkinfer pull --ff-only; else git clone https://github.com/0xSero/deepseek-v4-flash-0731-spark-sparkinfer {src_dir}/deepseek-v4-flash-0731-spark-sparkinfer; fi && cd {src_dir}/deepseek-v4-flash-0731-spark-sparkinfer && printf 'services:
  deepseek-v4-flash:
    container_name: mc-{slug}
    labels:
      - mc.runtime.slug={slug}
{env_yaml}' > compose.override.yaml && { TUNING=""; [ -f compose.tuning.yaml ] && TUNING="-f compose.tuning.yaml"; ARGS="-f compose.yaml $TUNING -f compose.override.yaml"; docker compose $ARGS pull && docker compose $ARGS up -d && ok=0 && for i in $(seq 1 480); do if curl -fsS --max-time 5 http://127.0.0.1:8000/health >/dev/null 2>&1; then ok=1; break; fi; if [ $((i % 20)) -eq 0 ]; then echo "MC: warte auf /health — $((i / 2)) min vergangen (der erste Start laedt ~107 GB Gewichte)."; fi; sleep 30; done && if [ "$ok" = 1 ]; then echo "MC: /health antwortet — der Stack serviert auf Port 8000."; else echo "MC: /health nach 4 h nicht erreicht — auf der Box 'docker compose $ARGS logs' pruefen."; false; fi; }

launch_template:
cd {src_dir}/deepseek-v4-flash-0731-spark-sparkinfer && printf 'services:
  deepseek-v4-flash:
    container_name: mc-{slug}
    labels:
      - mc.runtime.slug={slug}
{env_yaml}' > compose.override.yaml && { TUNING=""; [ -f compose.tuning.yaml ] && TUNING="-f compose.tuning.yaml"; ARGS="-f compose.yaml $TUNING -f compose.override.yaml"; docker compose $ARGS up -d; }
